import{_ as r,c as a,o as n,ag as t}from"./chunks/framework.DQvKz0xt.js";const c=JSON.parse('{"title":"Unreal - Rive 游戏运行时","description":"Rive 的 Unreal 运行时。 我们要重写我们的 Unreal Engine 集成以提供显着更好的性能，并且它已经显示出 4 倍的速度提升。为了专注于这项工作，我们暂时暂停支持，并且不再推荐当前版本的 Rive Unreal 插件（作为实验性预览版发布）。更多详细信息 在此。","frontmatter":{"title":"Unreal - Rive 游戏运行时","description":"Rive 的 Unreal 运行时。 我们要重写我们的 Unreal Engine 集成以提供显着更好的性能，并且它已经显示出 4 倍的速度提升。为了专注于这项工作，我们暂时暂停支持，并且不再推荐当前版本的 Rive Unreal 插件（作为实验性预览版发布）。更多详细信息 在此。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 游戏运行时, Unreal"}]]},"headers":[],"relativePath":"games/unreal.md","filePath":"games/unreal.md","lastUpdated":1774838907000}'),l={name:"games/unreal.md"};function i(p,e,o,s,u,h){return n(),a("div",null,[...e[0]||(e[0]=[t('<p>Unreal</p><h1 id="unreal" tabindex="-1">Unreal <a class="header-anchor" href="#unreal" aria-label="Permalink to &quot;Unreal&quot;">​</a></h1><p>Rive 的 Unreal 运行时。</p><p>我们要重写我们的 Unreal Engine 集成以提供显着更好的性能，并且它已经显示出 4 倍的速度提升。为了专注于这项工作，我们暂时暂停支持，并且不再推荐当前版本的 Rive Unreal 插件（作为实验性预览版发布）。更多详细信息 <a href="https://community.rive.app/c/announcements/rive-x-unreal" target="_blank" rel="noreferrer">在此</a>。</p><p>此页面适用于使用插件旧版本的用户。</p><p>请参阅下面的“<strong>功能支持</strong>”以获取 Unreal 中 Rive 功能的更新列表。</p><h2 id="​-渲染支持" tabindex="-1"><a href="#rendering-support">​</a> 渲染支持 <a class="header-anchor" href="#​-渲染支持" aria-label="Permalink to &quot;[​](#rendering-support) 渲染支持&quot;">​</a></h2><p>rive-unreal 运行时使用 <a href="https://rive.app/renderer" target="_blank" rel="noreferrer">Rive 渲染器</a> 并支持以下内容：</p><ul><li>Metal on Mac</li><li>Metal on iOS</li><li>Windows 上的 Vulkan, DirectX11, 和 DirectX12</li><li>Android 支持即将推出！</li></ul><p>计划支持：</p><ul><li>Linux 和 Android 上的 Vulkan。</li></ul><h2 id="​-错误报告" tabindex="-1"><a href="#bug-reports">​</a> 错误报告 <a class="header-anchor" href="#​-错误报告" aria-label="Permalink to &quot;[​](#bug-reports) 错误报告&quot;">​</a></h2><p>如果你在集成 Rive Unreal 运行时时遇到任何错误或意外崩溃，我们建议直接在 <a href="https://github.com/rive-app/rive-unreal/issues" target="_blank" rel="noreferrer">rive-unreal</a> 仓库中记录详细问题。</p><h2 id="​-功能支持" tabindex="-1"><a href="#feature-support">​</a> 功能支持 <a class="header-anchor" href="#​-功能支持" aria-label="Permalink to &quot;[​](#feature-support) 功能支持&quot;">​</a></h2><p>rive-unreal 运行时使用 <a href="https://github.com/rive-app/rive-cpp" target="_blank" rel="noreferrer">Rive C++ 运行时</a>。有关运行时支持的更多详细信息，请参阅 <a href="/docs/feature-support">功能支持</a> 页面。</p><p><a href="https://help.rive.app/game-runtimes/unreal/getting-started" target="_blank" rel="noreferrer">快速开始</a></p>',16)])])}const f=r(l,[["render",i]]);export{c as __pageData,f as default};
